var DEFAULT_OVERLAY_STYLE_PRESET = "minimal";
function getOverlayStylePreset(id) {
  return OVERLAY_STYLE_PRESETS.find((preset) => preset.id === id) ?? OVERLAY_STYLE_PRESETS[0];
}
function createDefaultOverlayStyle(preset = DEFAULT_OVERLAY_STYLE_PRESET) {
  return { ...getOverlayStylePreset(preset).style };
}
